from taf.ul.trs_e2e_fw.lib.utils.board_operations.rrb_manager import Rrb


def rrb_reset(**kwargs):
    """
     This keyword can be used to reset RRB.

    | *Arguments* | *Default* | *Comments* |
    | dut | 'bts' | Detail of the given dut will be fetched from `testline_config.json` file |
    | timeout | 300 | Timeout in seconds for the operation |
    | force_reset | True | Make it False, if force reset is not required |
    | retry | False | Make it True, if retry is required  |

    *Usage* \n
    Rrb Reset  | dut=bts | timeout=200 | force_reset=False | retry=True |

    *Return* \n

    *Exceptions* \n
        Exception, If dut does not come up
        Exception, If dut does not go down
    """
    dut = kwargs.get("dut", "bts")
    force_reset = kwargs.get("force_reset", True)
    retry = kwargs.get("retry", False)
    timeout = kwargs.get("timeout", 300)
    Rrb().rrb_reset(dut, force_reset, retry, timeout)


def turn_on_rrb(**kwargs):
    """
    This keyword can be used to Turn On RRB.

    | *Arguments* | *Default* | *Comments* |
    | dut | 'bts' | Detail of the given dut will be fetched from `testline_config.json` file |
    | timeout | 300 | Timeout in seconds for the operation |
    | retry | False | Make it True, if retry is required  |

    *Usage* \n
    Turn On Rrb  | dut=bts | timeout=200 | retry=True |

    *Return* \n

    *Exceptions* \n
        Exception, If dut is not coming up
    """
    dut = kwargs.get("dut", "bts")
    retry = kwargs.get("retry", False)
    timeout = kwargs.get("timeout", 300)
    Rrb().on(dut=dut, retry=retry, timeout=timeout)


def turn_off_rrb(**kwargs):
    """
    This keyword can be used to reset RRB.

    *Usage* \n
    Turn Off Rrb  | dut=bts | timeout=200 |

    | *Arguments* | *Default* | *Comments* |
    | dut | 'bts' | Detail of the given dut will be fetched from `testline_config.json` file |
    | timeout | 120 | Timeout in seconds for the operation |

    *Return* \n

    *Exceptions* \n
        Exception, If dut is not going down
    """
    dut = kwargs.get("dut", "bts")
    timeout = kwargs.get("timeout", 120)
    Rrb().off(dut=dut, timeout=timeout)
